using System;using System.IO;using System.Linq;using System.Text;using UnityEngine;using UnityEditor;using UnityEngine.SceneManagement;
[InitializeOnLoad]public static class RoadCarScaleAudit{static RoadCarScaleAudit(){EditorApplication.update+=Poll;}static void Poll(){if(EditorApplication.isCompiling||!File.Exists("RoadCarScaleAudit.request"))return;File.Delete("RoadCarScaleAudit.request");try{Run();}catch(Exception e){File.WriteAllText("FinalEnvironmentRoadReview/RoadCarScaleAudit.txt",e.ToString());}}static void Car(GameObject g,StringBuilder s,string label){var points=g.GetComponentsInChildren<MeshFilter>(true).Where(f=>f.sharedMesh&&!f.name.ToLower().Contains("collider")).SelectMany(f=>{var b=f.sharedMesh.bounds;return new[]{new Vector3(b.min.x,b.min.y,b.min.z),new Vector3(b.max.x,b.min.y,b.min.z),new Vector3(b.min.x,b.max.y,b.min.z),new Vector3(b.max.x,b.max.y,b.min.z),new Vector3(b.min.x,b.min.y,b.max.z),new Vector3(b.max.x,b.min.y,b.max.z),new Vector3(b.min.x,b.max.y,b.max.z),new Vector3(b.max.x,b.max.y,b.max.z)}.Select(v=>g.transform.InverseTransformPoint(f.transform.TransformPoint(v)));}).ToArray();if(points.Length==0)return;var b2=new Bounds(points[0],Vector3.zero);foreach(var v in points)b2.Encapsulate(v);s.AppendLine(label+" "+g.name+" localMeshBounds="+b2.size.ToString("F4")+" lossyScale="+g.transform.lossyScale.ToString("F4")+" axisScaledSize="+Vector3.Scale(b2.size,g.transform.lossyScale).ToString("F4"));}
static void Run(){var s=new StringBuilder();var scenes=Enumerable.Range(0,SceneManager.sceneCount).Select(SceneManager.GetSceneAt).ToArray();foreach(var sc in scenes){s.AppendLine("SCENE "+sc.path);foreach(var g in sc.GetRootGameObjects().SelectMany(r=>r.GetComponentsInChildren<Transform>(true)).Where(t=>t.name=="Prometheus"||t.name.Contains("Free Racing Car")))Car(g.gameObject,s,"SCENE VEHICLE");var roads=sc.GetRootGameObjects().SelectMany(r=>r.GetComponentsInChildren<MeshFilter>(true)).Where(f=>f.sharedMesh&&f.GetComponent<Renderer>()&&f.GetComponent<Renderer>().sharedMaterials.Any(m=>m&&(m.name=="Road Atlas"||m.name=="City PNG Markings"))).ToArray();foreach(var f in roads.Where(f=>{var b=f.GetComponent<Renderer>().bounds;return Mathf.Max(b.size.x,b.size.z)>70&&Mathf.Min(b.size.x,b.size.z)>10&&Mathf.Min(b.size.x,b.size.z)<40;}).Take(25)){var b=f.GetComponent<Renderer>().bounds;s.AppendLine("ROAD "+f.name+" bounds="+b.ToString("F4")+" material="+f.GetComponent<Renderer>().sharedMaterial.name+" mesh="+AssetDatabase.GetAssetPath(f.sharedMesh));}}
foreach(var path in new[]{"Assets/PROMETEO - Car Controller/Prefabs/Prometheus.prefab","Assets/ARCADE - FREE Racing Car/Prefabs (With Colliders)/Free Racing Car.prefab"}){var g=AssetDatabase.LoadAssetAtPath<GameObject>(path);if(g)Car(g,s,"PREFAB "+path);}File.WriteAllText("FinalEnvironmentRoadReview/RoadCarScaleAudit.txt",s.ToString());}}
